import { Box, CircularProgress, Container, Grid } from "@mui/material";
import proPic from "../assets/proPic.jfif";
import FlagPlihipin from "../assets/FlagPlihipin.png";
import React, { useContext, useEffect, useState } from "react";
import EmpCard from "../components/EmpCard";
import { Link, useParams } from "react-router-dom";
import { GetEmployeeByID } from "../lib/api";
import { UserContext } from "../Context/UserContext";

export default function EmpProfile() {
  window.scrollTo(0, 0);
  const { accessToken } = useContext(UserContext);
  const [employee, setEmployee] = useState("");
  let { id } = useParams();

  async function getEmployee(accessToken) {
    const { data, status } = await GetEmployeeByID(id, accessToken);

    if (status) {
      setEmployee(data);
    }
  }
  useEffect(() => {
    getEmployee(accessToken);
  }, []);
  return (
    <Container sx={{ "& > div:not(:last-child)": { marginBottom: "3rem" } }}>
      {employee ? (
        <>
          <Landing
            employee={employee}
            name={"أليس ديكسون"}
            proPic={proPic}
            Information={[]}
          />
          {/* <AdditionalInfo employee={employee} /> */}
        </>
      ) : (
        <>
          <Grid
            container
            sx={{
              display: "flex",
              justifyContent: "center",
              alignContent: "center",
              height: "100vh",
            }}
          >
            <CircularProgress size={"2.5rem"} />
          </Grid>
        </>
      )}

      {/* <Recommendation recommendations={[1, 2, 3]} /> */}
    </Container>
  );
}

